  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Old Marlow, if the lamp is still lit.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:e41291e5-ac69-4bc5-97b3-64a83fda1feb"],
    "speaker_id": "e41291e5-ac69-4bc5-97b3-64a83fda1feb"
