[
  {
    "kind": "narration",
    "text": "Wren tries to catch Ash's attention, eager to ask a question.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, noticing Wren, pauses in her task.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Stalls open at second bell.\"",
    "speaker_id": "db3bf895-978c-4263-9c26-4594f5203265",
    "cited_fact_keys": ["reaction:1a9de298-959e-556e-aa27-e12fee6bc996"]
