  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation about their dawn patrol plans.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash, however, seems preoccupied and doesn't respond immediately.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
