]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Marlow attempts to communicate with Ash, warning about the road past the hearth.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash waits for a moment.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Ash turns to Wren, saying, 'Dawn bell means the first stalls are opening.'",
    "cited_fact_keys": ["reaction:227e9d2f-4dec-57cd-885a-b056cbadcf3c"],
    "speaker_id": "65e37b74-d528-49fa-b1b7-bf5bfc77744f"
  },
  {
    "kind": "dialogue",
    "text": "Marlow adds, 'Aye, and mind the loose stones past the bridge.'",
    "cited_fact_keys": ["reaction:75d92072-c90d-50b7-acf7-74885289832d"],
    "speaker_id": "63d8b2de-a4aa-4c77-a0b3-3301804f8ec8"
  }
]

[
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Wren attempts to communicate with Ash about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Meanwhile, Marlow observes the scene.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Ash, patiently waiting, turns to Wren.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "33e37458-383a-468a-9eff-5d9612657689",
    "text": "\"Dawn bell means the market's waking.\"",
    "cited_fact_keys": ["reaction:4e3981e1-d0e0-50ba-aa04-cc9c18fc435b"]
  }
]

[
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": ["attempt:communicate"],
    "text": "Wren attempts to communicate with Ash, trying to convey a message about their journey ahead."
  },
  {
    "kind": "dialogue",
    "speaker_id": "cfe877aa-1969-41f4-845d-3443712ef831",
    "cited_fact_keys": ["reaction:545ec852-ca9c-5e4d-a178-130d8f0520fc"],
    "text": "Ash says to Wren, 'Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.'"
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": ["attempt:wait"],
    "text": "Meanwhile, Ash patiently waits for Wren's response."
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Is the old bridge safe to cross?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "'No.', Ash responds.",
    "cited_fact_keys": ["reaction:1c9a75e5-11b3-5758-8df1-42cc7eb28a94"],
    "speaker_id": "43e13ab2-64c5-4dcc-8f87-5f6071fd5933"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation, asking about the mill.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "cd8ee8a3-3245-4a88-a438-7d4600f3feeb",
    "text": "\"It's still standing, unless someone's moved it.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:2d7e6109-bbdc-582a-9967-81982647cb11"]
  },
  {
    "kind": "narration",
    "text": "Ash waits for Wren's next move.",
    "cited_fact_keys": ["attempt:wait"]
  }
]
